// ---------------------------------------------------------------------------
// WebSocket message protocol for Vaani Setu
//
// Every message is a JSON string with a discriminating `type` field.
// Audio data is base64-encoded inside the JSON payload.
//
// Client ──► Server:  ClientMessage
// Server ──► Client:  ServerMessage
// ---------------------------------------------------------------------------

import type { LanguageCode } from './languages.js';

// ── Helpers ────────────────────────────────────────────────────────────────

/** Unique ID generated by the client for each recording turn. */
export type UtteranceId = string;

// ── Client → Server ────────────────────────────────────────────────────────

/**
 * Sent once when the user opens the page.
 * Establishes the source ↔ target language pair for this session.
 */
export interface StartSessionMessage {
  type: 'start_session';
  sourceLanguage: LanguageCode;
  targetLanguage: LanguageCode;
}

/**
 * A chunk of PCM16 mono 16 kHz audio, base64-encoded.
 * Sent continuously while the mic is active.
 */
export interface AudioChunkClientMessage {
  type: 'audio_chunk';
  utteranceId: UtteranceId;
  /** Base64-encoded PCM16 LE mono 16 kHz audio. */
  audio: string;
  /** Sequence number within this utterance (0-based). */
  seq: number;
}

/**
 * The user stopped recording. The server should process the buffered audio
 * for this utterance.
 */
export interface EndUtteranceMessage {
  type: 'end_utterance';
  utteranceId: UtteranceId;
}

/**
 * Swap source ↔ target language for the next utterance.
 * (e.g. Speaker A was Odia→Tamil, Speaker B is Tamil→Odia)
 */
export interface SwapLanguagesMessage {
  type: 'swap_languages';
}

/** Discriminated union of every message the client can send. */
export type ClientMessage =
  | StartSessionMessage
  | AudioChunkClientMessage
  | EndUtteranceMessage
  | SwapLanguagesMessage;

/** String literal union of client message type tags. */
export type ClientMessageType = ClientMessage['type'];

// ── Server → Client ────────────────────────────────────────────────────────

/**
 * Interim STT result while audio is still streaming in.
 * The UI can show this as grey / "working" text.
 */
export interface PartialTranscriptMessage {
  type: 'partial_transcript';
  utteranceId: UtteranceId;
  text: string;
  language: LanguageCode;
}

/**
 * Final, stable STT transcript for the utterance.
 */
export interface FinalTranscriptMessage {
  type: 'final_transcript';
  utteranceId: UtteranceId;
  text: string;
  language: LanguageCode;
}

/**
 * Translated text from source → target language.
 */
export interface TranslationMessage {
  type: 'translation';
  utteranceId: UtteranceId;
  text: string;
  sourceLanguage: LanguageCode;
  targetLanguage: LanguageCode;
}

/**
 * TTS audio for the translated text, base64-encoded.
 */
export interface TtsAudioMessage {
  type: 'tts_audio';
  utteranceId: UtteranceId;
  /** Base64-encoded audio (WAV by default). */
  audio: string;
  /** MIME type of the audio, e.g. "audio/wav". */
  mimeType: string;
}

/**
 * Measured latency for each pipeline stage (in milliseconds).
 * Only reports real wall-clock time — no estimates or fabricated numbers.
 */
export interface LatencyMessage {
  type: 'latency';
  utteranceId: UtteranceId;
  /** Speech-to-text duration (ms). */
  sttMs: number;
  /** Translation duration (ms). */
  translateMs: number;
  /** Text-to-speech duration (ms). */
  ttsMs: number;
  /** Total pipeline duration (ms). */
  totalMs: number;
}

/**
 * Something went wrong during processing.
 */
export interface ErrorMessage {
  type: 'error';
  /** Absent for session-level errors (e.g. bad start_session). */
  utteranceId?: UtteranceId;
  code: ErrorCode;
  message: string;
}

/** Known error codes. */
export type ErrorCode =
  | 'invalid_message'
  | 'invalid_language'
  | 'stt_failed'
  | 'translate_failed'
  | 'tts_failed'
  | 'session_not_started'
  | 'provider_unavailable'
  | 'unknown';

/** Discriminated union of every message the server can send. */
export type ServerMessage =
  | PartialTranscriptMessage
  | FinalTranscriptMessage
  | TranslationMessage
  | TtsAudioMessage
  | LatencyMessage
  | ErrorMessage;

/** String literal union of server message type tags. */
export type ServerMessageType = ServerMessage['type'];

// ── Serialization helpers ──────────────────────────────────────────────────

/** Serialize a message to a JSON string for ws.send(). */
export function encodeMessage<T extends ClientMessage | ServerMessage>(
  msg: T,
): string {
  return JSON.stringify(msg);
}

/**
 * Parse a raw WebSocket text payload. Returns `null` on invalid JSON.
 * Callers must narrow the result with their own type guard.
 */
export function decodeMessage(raw: string): unknown {
  try {
    return JSON.parse(raw) as unknown;
  } catch {
    return null;
  }
}

/** Type-guard: does the payload look like a ClientMessage? */
export function isClientMessage(msg: unknown): msg is ClientMessage {
  if (typeof msg !== 'object' || msg === null) return false;
  const type = (msg as Record<string, unknown>)['type'];
  return (
    type === 'start_session' ||
    type === 'audio_chunk' ||
    type === 'end_utterance' ||
    type === 'swap_languages'
  );
}

/** Type-guard: does the payload look like a ServerMessage? */
export function isServerMessage(msg: unknown): msg is ServerMessage {
  if (typeof msg !== 'object' || msg === null) return false;
  const type = (msg as Record<string, unknown>)['type'];
  return (
    type === 'partial_transcript' ||
    type === 'final_transcript' ||
    type === 'translation' ||
    type === 'tts_audio' ||
    type === 'latency' ||
    type === 'error'
  );
}
